// Oracle differential compare. See state_diff.hpp for the policy.
#include "state_diff.hpp"

#include <cstdio>
#include <string>
#include <string_view>

namespace andes_sim {

namespace {

void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
         unsigned long long got) {
  ++r.compared;
  if (ref != got) r.diffs.push_back({field, ref, got});
}

}  // namespace

DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
                       const std::vector<std::string>& andes_supported) {
  DiffReport r;

  cmp(r, "magic", ref.magic, got.magic);
  cmp(r, "version", ref.version, got.version);
  cmp(r, "flags", ref.flags, got.flags);
  cmp(r, "hart_id", ref.hart_id, got.hart_id);
  cmp(r, "priv", ref.priv, got.priv);
  cmp(r, "pc", ref.pc, got.pc);

  // mepc/mcause: in the trap-free hybrid ROI they round-trip (L24: restored at
  // resume, re-read at drain). mtval/mstatus stay out of scope where they are
  // implementation-defined / carry dirty bits (false positives).
  cmp(r, "mepc", ref.mepc, got.mepc);
  cmp(r, "mcause", ref.mcause, got.mcause);

  // Round-trip M-mode CSRs: mscratch (L23) and mtval/mie (L24) are restored at
  // resume and re-read at drain, so a trap-free ROI must match the oracle on
  // them. mip is excluded: its pending bits are hardware/platform-driven
  // (timer/external) and diverge between QEMU's functional clock and vsim's
  // cycle clock even with no trap (it still round-trips into the drained
  // record, just not the verifier).
  cmp(r, "mscratch", ref.mscratch, got.mscratch);
  cmp(r, "mtval", ref.mtval, got.mtval);
  cmp(r, "mie", ref.mie, got.mie);

  for (int i = 0; i < 32; ++i)
    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);

  if (ref.flags & HYBRID_FLAG_FP) {
    for (int i = 0; i < 32; ++i)
      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
  }

  if (ref.flags & HYBRID_FLAG_V) {
    cmp(r, "vstart", ref.vstart, got.vstart);
    cmp(r, "vtype", ref.vtype, got.vtype);
    cmp(r, "vl", ref.vl, got.vl);
    cmp(r, "vlenb", ref.vlenb, got.vlenb);
    cmp(r, "vxsat", ref.vxsat, got.vxsat);
    cmp(r, "vxrm", ref.vxrm, got.vxrm);
    cmp(r, "vcsr", ref.vcsr, got.vcsr);

    // One compared "field" per vector register; report the first differing
    // byte as "v<i>[<byte>]".
    for (int i = 0; i < 32; ++i) {
      ++r.compared;
      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
        if (a[j] != b[j]) {
          r.diffs.push_back({"v" + std::to_string(i) + "[" +
                                 std::to_string(j) + "]",
                             a[j], b[j]});
          break;
        }
      }
    }
  }

  // Andes V5 CSR block (v3): the boot-static memory-system/extension CSRs plus
  // the DSP overflow flag round-trip through the trap-free ROI (ResumeDriver
  // restores them, StateDrain re-reads them), so a correct transport matches the
  // oracle. The X-macro is the single source of truth shared with the plugin
  // drain / resume / drain re-read, so this list can never drift out of sync.
  //
  // Exclusion: msp_bound/msp_base are the HW stack-protection bound registers.
  // QEMU resets them to all-ones; a vsim core that does not implement HW stack
  // protection drains 0. That divergence is an engine-implementation artifact,
  // not a transport bug (the restore is a tolerant no-op on a core lacking the
  // CSR) -- so they are transported but excluded from strict verify, exactly
  // like mip's hardware-driven pending bits.
  auto andes_verify_excluded = [](std::string_view name) {
    // msp_bound/msp_base: engine-reset-divergent HW stack-protection bounds.
    // milmb/mdlmb: ILM/DLM base+enable CSRs. The base address round-trips, but
    // the enable bit (bit 0) is HW-presence state -- the vsim RTL has the local
    // memories and drains EN=1, while QEMU models none and drains EN=0. Same
    // class as msp_bound/msp_base (an engine-implementation artifact, not a
    // transport bug), so excluded rather than half-compared via a bit mask.
    // mhpmcounter3..6: hardware performance counters that increment DURING the
    // ROI, so the vsim (cycle) and QEMU (functional) values legitimately differ
    // -- transported and restored, but not strict-compared, like mcycle/mip.
    // mdcause: vsim models it as HW-set (a direct write drains back 0).
    // tdata1/tcontrol/mcontext: debug-trigger state whose reset defaults and
    // WARL widths differ between QEMU and vsim. All transported + restored, but
    // not cross-engine strict-compared.
    return name == "msp_bound" || name == "msp_base" ||
           name == "milmb" || name == "mdlmb" ||
           name == "mhpmcounter3" || name == "mhpmcounter4" ||
           name == "mhpmcounter5" || name == "mhpmcounter6" ||
           name == "mdcause" || name == "tdata1" ||
           name == "tcontrol" || name == "mcontext";
  };
  // Engine capability gate (S4): skip any Andes CSR the cycle engine does not
  // implement. Empty list = no engine info -> compare all (back-compat).
  auto andes_supported_csr = [&](std::string_view name) {
    if (andes_supported.empty()) return true;
    for (const std::string& s : andes_supported)
      if (s == name) return true;
    return false;
  };
  if (ref.flags & HYBRID_FLAG_ANDES) {
#define X(field, addr, name)                                  \
  if (!andes_verify_excluded(name) && andes_supported_csr(name)) \
    cmp(r, name, ref.andes.field, got.andes.field);
    HYBRID_ANDES_CSR_LIST(X)
#undef X
    if (andes_supported_csr("pmacfg"))
      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
        cmp(r, "pmacfg" + std::to_string(i), ref.andes.pmacfg[i],
            got.andes.pmacfg[i]);
    if (andes_supported_csr("pmaaddr"))
      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
        cmp(r, "pmaaddr" + std::to_string(i), ref.andes.pmaaddr[i],
            got.andes.pmaaddr[i]);
  }

  // M-ext CSR block (v4): same gate (the engine's supported list now includes
  // the M-ext names) and the same HW-driven exclusion. A CSR the engine lacks
  // is neither restored, drained, nor compared.
  if (ref.flags & HYBRID_FLAG_M_EXT) {
#define X(field, addr, name)                                    \
  if (!andes_verify_excluded(name) && andes_supported_csr(name)) \
    cmp(r, name, ref.m_ext.field, got.m_ext.field);
    HYBRID_M_EXT_CSR_LIST(X)
#undef X
  }

  return r;
}

void print_diff_report(const DiffReport& r) {
  for (const FieldDiff& d : r.diffs)
    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
                d.ref, d.got);
  if (r.ok()) {
    std::printf(
        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
        "excluded)\n",
        r.compared);
  } else {
    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
                r.diffs.size(), r.compared);
  }
}

}  // namespace andes_sim

// Wire contract between the QEMU TCG plugin and vsim. Both sides write/read
// `struct hybrid_state_v1` byte-for-byte through a shared file.
//
// Stability: never repurpose offsets within a published version. Add new
// fields by consuming bytes from `reserved`, or by introducing v2 alongside.
//
// Endianness: multi-byte fields are little-endian (native on RV64 + x86-64
// host). The format is not endian-portable; cross-endian use would need an
// explicit byte-swap path.
//
// C and C++ both compile this header.

#ifndef HYBRID_STATE_ABI_H
#define HYBRID_STATE_ABI_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

#define HYBRID_STATE_MAGIC   0x42594841u  // 'AHYB' little-endian
// Version 4 (M-ext): append struct hybrid_m_ext_csr after the Andes block --
// the writable M-mode CSRs across the whole AndeStar V5 SPA (NMI, CLIC, perf
// counters, trap-save, triggers, state-enable, ...), transported forward-looking
// and capability-gated per engine. Version 3 (Andes F0) appended
// struct hybrid_andes_csr after mmisc_ctl. Version 2 (L11) widened vreg[] to
// 128 bytes/register. Readers reject older files loudly (all three consumers
// check magic + version + size) instead of mis-parsing them.
#define HYBRID_STATE_VERSION 4u

#define HYBRID_FLAG_RV64  (1u << 0)
#define HYBRID_FLAG_FP    (1u << 1)
#define HYBRID_FLAG_V     (1u << 2)
// v3: the struct hybrid_andes_csr block carries live values (the producer ran
// on an Andes core that implements at least one of those CSRs). Clear means the
// block is all-zero and consumers skip restore/re-read/compare of it.
#define HYBRID_FLAG_ANDES (1u << 3)
// v4: the struct hybrid_m_ext_csr block carries live values (the producer's
// gdbstub advertised at least one of those CSRs). Clear means the block is
// all-zero and consumers skip restore/re-read/compare of it.
#define HYBRID_FLAG_M_EXT (1u << 4)

// VLEN upper bound, in bytes: 128 covers the supported engine range
// VLEN 128..1024 (L11; also QEMU's RV_VLEN_MAX). This is the wire-format
// span per vector register; the LIVE width is the runtime `vlenb` field
// below, so one struct layout serves every engine config and the legs
// never disagree on offsets. A producer whose vlenb exceeds this ceiling
// must refuse to drain (see hybrid_v_drain_policy) rather than truncate.
#define HYBRID_VLEN_BYTES_MAX 128

// L26: bytes reserved for the V-register transport scratch page -- 32 vector
// registers at the wire-format span. The driver maps this many bytes ABOVE
// the program's --mem-size (so the scratch sits past the program's RAM), and
// vsim's v_scratch_gpa() / kVScratchBytes use the same count. Shared here so
// the producer (driver mmap sizing) and consumer (vsim sweep) never disagree.
#define HYBRID_V_SCRATCH_BYTES (32 * HYBRID_VLEN_BYTES_MAX)

// 64 PMP entries; pmpcfg slots reserved at 16 so the layout works for both
// RV64 (8 entries/CSR) and a future RV32 (4 entries/CSR) packing.
#define HYBRID_PMP_CFG_NUM  16
#define HYBRID_PMP_ADDR_NUM 64

// v3 Andes CSR block. PMA is 16 entries: pmacfg packs them at one byte each, so
// on RV64 only the even-numbered cfg CSRs exist -- 16 entries live in pmacfg0
// (0xBC0) + pmacfg2 (0xBC2), hence 2 cfg slots; 16 pmaaddr (0xBD0..0xBDF).
#define HYBRID_PMA_CFG_NUM  2
#define HYBRID_PMA_ADDR_NUM 16
#define HYBRID_PMA_CFG0_CSR   0xBC0
#define HYBRID_PMA_ADDR0_CSR  0xBD0

// Single source of truth for the SCALAR Andes CSRs transported in v3: X(field,
// csr_addr, gdb_name). Every consumer (QEMU plugin drain, ResumeDriver restore,
// StateDrain re-read, driver state_diff verify) iterates this list, so adding a
// CSR is one line here -- no consumer edits drift out of sync. PMA (arrays) is
// transported separately, mirroring the existing PMP loops. Each field is a
// 64-bit CSR value; 0 means the producing engine did not implement it (a
// tolerant no-op on restore). Order fixes the struct layout -- append only.
#define HYBRID_ANDES_CSR_LIST(X)            \
  X(mxstatus,       0x7C4, "mxstatus")      \
  X(mpft_ctl,       0x7C5, "mpft_ctl")      \
  X(mclk_ctl,       0x7DF, "mclk_ctl")      \
  X(milmb,          0x7C0, "milmb")         \
  X(mdlmb,          0x7C1, "mdlmb")         \
  X(mecc_code,      0x7C2, "mecc_code")     \
  X(mhsp_ctl,       0x7C6, "mhsp_ctl")      \
  X(msp_bound,      0x7C7, "msp_bound")     \
  X(msp_base,       0x7C8, "msp_base")      \
  X(mcountermask_m, 0x7D1, "mcountermask_m")\
  X(uitb,           0x800, "uitb")          \
  X(jvt,            0x017, "jvt")           \
  X(ucode,          0x801, "ucode")

// The Andes V5 machine/user CSRs a bare-metal Andes core sets up before the ROI
// (boot-static memory system + extension config) plus the DSP overflow flag.
// Restored at resume, re-read at drain, and verified -- live only when
// HYBRID_FLAG_ANDES is set. 13 scalar fields (above) + PMA = 31 * uint64_t.
struct hybrid_andes_csr {
#define HYBRID_ANDES_FIELD(field, addr, name) uint64_t field;
  HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
#undef HYBRID_ANDES_FIELD
  uint64_t pmacfg[HYBRID_PMA_CFG_NUM];
  uint64_t pmaaddr[HYBRID_PMA_ADDR_NUM];
};

// v4: the writable M-mode CSRs across the whole AndeStar V5 SPA that a
// bare-metal M / M+U ROI can hold as plain architectural state -- everything
// the spec defines as readable+writable with no read/write side effects, minus
// the blocks already carried above (standard M trap CSRs, the v3 Andes block,
// PMP, PMA, FP, V). Same single-source-of-truth X-macro pattern as
// HYBRID_ANDES_CSR_LIST: X(field, csr_addr, gdb_name). Every consumer (plugin
// drain, ResumeDriver restore, StateDrain re-read, driver state_diff verify)
// iterates this list, so adding a CSR is one line. Each is capability-gated by
// CSR address (src/hybrid/andes_caps.hpp): an engine that lacks the feature
// no-ops the restore/drain, so the block is transported forward-looking -- a
// core that implements it (CLIC, Smrnmi, Smstateen, ePMP, ...) round-trips it
// with no further change. Order fixes the struct layout -- append only.
#define HYBRID_M_EXT_CSR_LIST(X)                \
  X(menvcfg,         0x30A, "menvcfg")          \
  X(mseccfg,         0x747, "mseccfg")          \
  X(mcounteren,      0x306, "mcounteren")       \
  X(mcountinhibit,   0x320, "mcountinhibit")    \
  X(mhpmcounter3,    0xB03, "mhpmcounter3")     \
  X(mhpmcounter4,    0xB04, "mhpmcounter4")     \
  X(mhpmcounter5,    0xB05, "mhpmcounter5")     \
  X(mhpmcounter6,    0xB06, "mhpmcounter6")     \
